// Loop through all incoming items from the n8n node
return $input.all().map(item => {
  // If the data is coming in as a JSON string, parse it. 
  // If it's already an object, this handles it gracefully.
  let rawData = item.json.text || item.json;

  if (typeof rawData === 'string') {
    try {
      rawData = JSON.parse(rawData);
    } catch (e) {
      // Handle parsing error if JSON is malformed
      return { json: { error: "Invalid JSON format", original: rawData } };
    }
  }

  // Clean and validate fields
  let email = rawData.Email;
  let isEmailValid = true;

  // Example check for placeholder or invalid emails
  if (!email || email === "INVALID_EMAIL" || !email.includes("@")) {
    email = null; // or set a default / empty string
    isEmailValid = false;
  }

  // Return the cleaned and parsed object structure
  return {
    json: {
      Student_ID: rawData.Student_ID,
      Name: rawData.Name ? rawData.Name.trim() : "",
      Email: email,
      Email_Valid: isEmailValid, // Useful flag for filtering later
      Phone: rawData.Phone ? rawData.Phone.toString().trim() : "",
      Course: rawData.Course,
      Fee_Paid: Boolean(rawData.Fee_Paid),
      City: rawData.City ? rawData.City.trim() : "",
      Enrolled_Date: rawData.Enrolled_Date ? new Date(rawData.Enrolled_Date).toISOString().split('T')[0] : null
    }
  };
});
